Write {"file_path":"D:\code\ESI.ts\tests\bdd\step-definitions\core\pi.steps.ts","content":"import { defineFeature, loadFeature } from 'jest-cucumber';
import { EsiClient } from '../../../../src/EsiClient';
import { EsiError } from '../../../../src/core/util/error';
import { TestDataFactory } from '../../../../src/testing/TestDataFactory';

const feature = loadFeature('tests/bdd/features/core/pi.feature');

defineFeature(feature, (test) => {
  let client: EsiClient;

  beforeEach(() => {
    client = new EsiClient({
      clientId: 'test-client',
      baseUrl: 'https://esi.evetech.net',
      accessToken: 'mock-access-token',
      timeout: 5000,
    });
  });

  test('WHEN getColonies is called, the client shall return a list of planetary colonies', ({ given, when, then }) => {
    let result: any;
    const characterId = 90000001;
    const expectedColonies = [
      {
        planet_id: 40000001,
        planet_type: 'temperate',
        solar_system_id: 30000142,
        num_pins: 8,
        last_update: '2024-03-15T10:00:00Z',
        owner_id: characterId,
        upgrade_level: 5,
      },
      {
        planet_id: 40000002,
        planet_type: 'barren',
        solar_system_id: 30000142,
        num_pins: 6,
        last_update: '2024-03-14T08:00:00Z',
        owner_id: characterId,
        upgrade_level: 4,
      },
    ];

    given('the ESI PI colonies endpoint is available', () => {
      jest
        .spyOn(client.pi, 'getColonies')
        .mockResolvedValue(expectedColonies as any);
    });

    when('getColonies is called with a character ID', async () => {
      result = await client.pi.getColonies(characterId);
    });

    then('the client shall return an array of colonies with planet details', () => {
      expect(result).toBeDefined();
      expect(result).toHaveLength(2);
      expect(result[0].planet_id).toBe(40000001);
      expect(result[0].planet_type).toBe('temperate');
      expect(result[1].upgrade_level).toBe(4);
    });
  });

  test('WHEN getColonies returns no results, the client shall return an empty array', ({ given, when, then }) => {
    let result: any;
    const characterId = 90000001;

    given('the ESI PI colonies endpoint returns no colonies', () => {
      jest.spyOn(client.pi, 'getColonies').mockResolvedValue([]);
    });

    when('getColonies is called with a character ID that has no colonies', async () => {
      result = await client.pi.getColonies(characterId);
    });

    then('the client shall return an empty array', () => {
      expect(Array.isArray(result)).toBe(true);
      expect(result).toHaveLength(0);
    });
  });

  test('WHEN getColonyLayout is called, the client shall return pins, links, and routes', ({ given, when, then }) => {
    let result: any;
    const characterId = 90000001;
    const planetId = 40000001;
    const expectedLayout = {
      pins: [
        {
          pin_id: 1001,
          type_id: 2254,
          latitude: 0.5,
          longitude: 1.2,
          schematic_id: 130,
        },
        {
          pin_id: 1002,
          type_id: 2256,
          latitude: 0.6,
          longitude: 1.3,
          schematic_id: 0,
        },
      ],
      links: [{ source_pin_id: 1001, destination_pin_id: 1002, link_level: 0 }],
      routes: [
        {
          route_id: 5001,
          source_pin_id: 1001,
          destination_pin_id: 1002,
          content_type_id: 2389,
          quantity: 100,
        },
      ],
    };

    given('the ESI PI colony layout endpoint is available', () => {
      jest
        .spyOn(client.pi, 'getColonyLayout')
        .mockResolvedValue(expectedLayout as any);
    });

    when('getColonyLayout is called with a character ID and planet ID', async () => {
      result = await client.pi.getColonyLayout(characterId, planetId);
    });

    then('the client shall return a layout containing pins, links, and routes', () => {
      expect(result).toBeDefined();
      expect(result.pins).toHaveLength(2);
      expect(result.links).toHaveLength(1);
      expect(result.routes).toHaveLength(1);
      expect(result.links[0].source_pin_id).toBe(1001);
      expect(result.links[0].destination_pin_id).toBe(1002);
    });
  });

  test('WHEN getColonyLayout is called for an empty colony, the client shall return empty arrays', ({ given, when, then }) => {
    let result: any;
    const characterId = 90000001;
    const planetId = 40000003;
    const emptyLayout = { pins: [], links: [], routes: [] };

    given('the ESI PI colony layout endpoint returns an empty layout', () => {
      jest
        .spyOn(client.pi, 'getColonyLayout')
        .mockResolvedValue(emptyLayout as any);
    });

    when('getColonyLayout is called with a character ID and an empty planet ID', async () => {
      result = await client.pi.getColonyLayout(characterId, planetId);
    });

    then('the client shall return empty arrays for pins, links, and routes', () => {
      expect(result.pins).toHaveLength(0);
      expect(result.links).toHaveLength(0);
      expect(result.routes).toHaveLength(0);
    });
  });

  test('WHEN getSchematicInformation is called, the client shall return schematic details', ({ given, when, then }) => {
    let result: any;
    const schematicId = 130;
    const expectedSchematic = {
      schematic_id: 130,
      schematic_name: 'Bacteria',
      cycle_time: 1800,
    };

    given('the ESI PI schematic endpoint is available', () => {
      jest
        .spyOn(client.pi, 'getSchematicInformation')
        .mockResolvedValue(expectedSchematic as any);
    });

    when('getSchematicInformation is called with a schematic ID', async () => {
      result = await client.pi.getSchematicInformation(schematicId);
    });

    then('the client shall return schematic details including name and cycle time', () => {
      expect(result).toBeDefined();
      expect(result.schematic_name).toBe('Bacteria');
      expect(result.cycle_time).toBe(1800);
    });
  });

  test('IF schematic ID does not exist, THEN the client shall throw an EsiError with status 404', ({ given, when, then }) => {
    let caughtError: any;
    const schematicId = 999999;

    given('the ESI PI schematic endpoint returns a 404 for an invalid ID', () => {
      const error = TestDataFactory.createError(404);
      jest.spyOn(client.pi, 'getSchematicInformation').mockRejectedValue(error);
    });

    when('getSchematicInformation is called with an invalid schematic ID', async () => {
      try {
        await client.pi.getSchematicInformation(schematicId);
      } catch (e) {
        caughtError = e;
      }
    });

    then('the client shall throw an EsiError with status 404', () => {
      expect(caughtError).toBeInstanceOf(EsiError);
    });
  });

  test('WHEN getCorporationCustomsOffices is called, the client shall return a list of customs offices', ({ given, when, then }) => {
    let result: any;
    const corporationId = 1344654522;
    const expectedOffices = [
      {
        office_id: 7001,
        system_id: 30000142,
        planet_id: 40000001,
        reinforce_exit_start: 18,
        reinforce_exit_end: 21,
        alliance_tax_rate: 0.1,
        corporation_tax_rate: 0.05,
        standing_level: 'terrible',
        terrible_standing_tax_rate: 0.5,
      },
      {
        office_id: 7002,
        system_id: 30000143,
        planet_id: 40000010,
        reinforce_exit_start: 0,
        reinforce_exit_end: 3,
        alliance_tax_rate: 0.1,
        corporation_tax_rate: 0.05,
        standing_level: 'neutral',
        terrible_standing_tax_rate: 0.5,
      },
    ];

    given('the ESI PI customs offices endpoint is available', () => {
      jest
        .spyOn(client.pi, 'getCorporationCustomsOffices')
        .mockResolvedValue(expectedOffices as any);
    });

    when('getCorporationCustomsOffices is called with a corporation ID', async () => {
      result = await client.pi.getCorporationCustomsOffices(corporationId);
    });

    then('the client shall return an array of customs offices with office details', () => {
      expect(result).toBeDefined();
      expect(result).toHaveLength(2);
      expect(result[0].office_id).toBe(7001);
      expect(result[1].system_id).toBe(30000143);
    });
  });

  test('IF permissions are insufficient for customs offices, THEN the client shall throw an EsiError with status 403', ({ given, when, then }) => {
    let caughtError: any;
    const corporationId = 1344654522;

    given('the ESI PI customs offices endpoint rejects unauthorized requests', () => {
      const error = TestDataFactory.createError(403);
      jest
        .spyOn(client.pi, 'getCorporationCustomsOffices')
        .mockRejectedValue(error);
    });

    when('getCorporationCustomsOffices is called without sufficient permissions', async () => {
      try {
        await client.pi.getCorporationCustomsOffices(corporationId);
      } catch (e) {
        caughtError = e;
      }
    });

    then('the client shall throw an EsiError with status 403', () => {
      expect(caughtError).toBeInstanceOf(EsiError);
    });
  });

  test('WHEN colonies and layouts are retrieved sequentially, the client shall return complete PI data', ({
    given,
    when,
    then,
  }) => {
    let allColonies: any;
    let colonyLayout: any;
    const characterId = 90000001;
    const colonies = [
      {
        planet_id: 40000001,
        planet_type: 'temperate',
        solar_system_id: 30000142,
        num_pins: 5,
        last_update: '2024-03-15T10:00:00Z',
        owner_id: characterId,
        upgrade_level: 5,
      },
    ];
    const layout = {
      pins: [{ pin_id: 1001, type_id: 2254, latitude: 0.5, longitude: 1.2 }],
      links: [],
      routes: [],
    };

    given('the ESI PI colonies and colony layout endpoints are available', () => {
      jest.spyOn(client.pi, 'getColonies').mockResolvedValue(colonies as any);
      jest.spyOn(client.pi, 'getColonyLayout').mockResolvedValue(layout as any);
    });

    when('getColonies and getColonyLayout are called sequentially', async () => {
      allColonies = await client.pi.getColonies(characterId);
      colonyLayout = await client.pi.getColonyLayout(
        characterId,
        allColonies[0].planet_id,
      );
    });

    then('the client shall return complete PI data including colonies and layouts', () => {
      expect(allColonies).toHaveLength(1);
      expect(colonyLayout.pins).toHaveLength(1);
      expect(client.pi.getColonyLayout).toHaveBeenCalledWith(
        characterId,
        40000001,
      );
    });
  });
});
"}
